import 'dart:io';

import 'package:open_filex/open_filex.dart';
import 'package:path_provider/path_provider.dart';
import 'package:share_plus/share_plus.dart';

import '../network/downloaded_file.dart';

/// Saves generated bytes to temp storage and opens/shares them.
/// Remote URLs expire (~1h) and are never treated as permanent artifacts.
abstract final class FileSaver {
  /// Injectable for tests (defaults to the platform temp directory).
  static Future<Directory> Function() directoryProvider =
      getTemporaryDirectory;

  static String sanitize(String name) {
    final cleaned = name.replaceAll(RegExp(r'[^\w\-. ]'), '_').trim();
    if (cleaned.isEmpty) return 'utilza-result';
    return cleaned.length > 120 ? cleaned.substring(0, 120) : cleaned;
  }

  static Future<File> save(
    DownloadedFile file, {
    String? suggestedName,
  }) async {
    final dir = await directoryProvider();
    final name = sanitize(
      suggestedName ?? file.fileName ?? 'utilza-result',
    );
    var target = File('${dir.path}/$name');
    if (await target.exists()) {
      final stamp = DateTime.now().millisecondsSinceEpoch;
      target = File('${dir.path}/${stamp}_$name');
    }
    await target.writeAsBytes(file.bytes, flush: true);
    return target;
  }

  static Future<void> open(File file) async {
    await OpenFilex.open(file.path);
  }

  static Future<void> share(File file) async {
    await SharePlus.instance.share(
      ShareParams(files: [XFile(file.path)]),
    );
  }
}
